package com.enterprisehub.domain;
import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="audit_logs") public class AuditLog { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) public Long id; @ManyToOne @JoinColumn(name="request_id",nullable=false) public ServiceRequest request; @ManyToOne @JoinColumn(name="actor_id",nullable=false) public Employee actor; @Column(nullable=false) public String action; @Column(columnDefinition="json") public String details; @Column(name="old_value") public String oldValue; @Column(name="new_value") public String newValue; @Column(length=1000) public String reason; @Column(name="created_at",insertable=false,updatable=false) public Instant createdAt; protected AuditLog(){} public AuditLog(ServiceRequest r,Employee a,String action,String details){this.request=r;this.actor=a;this.action=action;this.details=details;} public AuditLog(ServiceRequest r,Employee a,String action,String oldValue,String newValue,String reason){this(r,a,action,"{}");this.oldValue=oldValue;this.newValue=newValue;this.reason=reason;} }
